**Stress harness** (used for the Proof row; not committed). `main.js`:

```js
// Stress harness: start()/stop() the uiohook-napi hook N times inside Electron,
// the way the app does once per recording, under a watchdog. A deadlock in
// hook_enable() shows up as the watchdog firing (the main thread never returns
// from start()). Run with the app's Electron binary from apps/kaipu-record so the
// app's node_modules (and its rebuilt binary) resolve:
//   <electron> <this dir> [iterations]
const path = require("node:path");
const { app, systemPreferences } = require("electron");

const APP_DIR = "/Users/cristiansotomayor-m5-pro/Documents/Workspace/Personal/kaipu-record-monorepo/.claude/worktrees/uiohook-deadlock/apps/kaipu-record";
const iterations = Number(process.argv[2] ?? 200);
const WATCHDOG_MS = 10_000;

app.whenReady().then(() => {
  if (!systemPreferences.isTrustedAccessibilityClient(false)) {
    console.log("[stress] accessibility NOT trusted for this Electron binary; the hook would be skipped by the app. Aborting.");
    app.exit(2);
    return;
  }
  const { uIOhook } = require(path.join(APP_DIR, "node_modules/uiohook-napi"));
  const binary = require.resolve(path.join(APP_DIR, "node_modules/uiohook-napi"));
  console.log(`[stress] module: ${binary}`);
  uIOhook.on("mousedown", () => {});

  let i = 0;
  const watchdog = setInterval(() => {
    // Runs only if the main thread is free: a deadlock inside start() stops it too,
    // so the external caller must also time the process (see run-stress.sh).
  }, 1000);
  const started = Date.now();
  for (i = 0; i < iterations; i++) {
    const t0 = Date.now();
    uIOhook.start();
    const dt = Date.now() - t0;
    uIOhook.stop();
    if (dt > 1000) console.log(`[stress] iteration ${i}: start() took ${dt} ms`);
  }
  clearInterval(watchdog);
  console.log(`[stress] OK: ${iterations} start/stop cycles in ${Date.now() - started} ms`);
  app.exit(0);
});

setTimeout(() => {
  console.log(`[stress] WATCHDOG: main thread blocked for ${WATCHDOG_MS} ms (hook deadlock)`);
  process.exit(3);
}, WATCHDOG_MS).unref();
```

Runner with external timeout and `sample` on hang:

```bash
#!/usr/bin/env bash
# Runs the stress harness under an external timeout (a deadlocked main thread
# cannot fire its own watchdog). Exit 0 = N cycles completed; 124 = hung.
set -uo pipefail
HERE="$(cd "$(dirname "$0")" && pwd)"
WT=/Users/cristiansotomayor-m5-pro/Documents/Workspace/Personal/kaipu-record-monorepo/.claude/worktrees/uiohook-deadlock
E="$WT/node_modules/.bun/electron@39.8.10/node_modules/electron/dist/Electron.app/Contents/MacOS/Electron"
N="${1:-200}"
echo '{"name":"stress","main":"main.js"}' > "$HERE/package.json"
"$E" "$HERE" "$N" > "$HERE/last-run.log" 2>&1 &
PID=$!
for _ in $(seq 1 40); do
  if ! kill -0 "$PID" 2>/dev/null; then break; fi
  sleep 0.5
done
if kill -0 "$PID" 2>/dev/null; then
  echo "HUNG after 20 s — sampling main thread, then kill -9"
  sample "$PID" 1 -file "$HERE/hung.sample" >/dev/null 2>&1
  grep -E "hook_enable|uv_thread_join|worker_dispatch_proc|uv_mutex_lock" "$HERE/hung.sample" | head -5
  kill -9 "$PID"
  exit 124
fi
wait "$PID"; RC=$?
grep "\[stress\]" "$HERE/last-run.log"
exit $RC
```

Result on the rebuilt binary: `[stress] OK: 50000 start/stop cycles in 6947 ms` (exit 0). On the unpatched prebuild: `OK: 50000 cycles in 5984 ms`. The race is not reproducible by brute force; the recorded `sample` of the hung process (pid 3696, 2026-10-28) is the repro.
